    @GameTest(structure="create_test:reservoir") public void actualSafeNbtWriterStoppingSourceAfterProtectionCannotDebitOrCreatePendingPayment(GameTestHelper h)throws Exception{
        try(var session=GameplayAdvancementGameTests.join(h);var blueprint=new Blueprint(h,session.player(),GameplayPrintTestFixtures.NBT_CALLBACK.defaultBlockState());var scene=new Scene(h,session.player(),blueprint.item,GameplayPrintTestFixtures.NBT_CALLBACK.asItem())){
            scene.fund();var seen=new AtomicInteger();try(var callback=GameplayPrintTestFixtures.afterPermissionBeforeSafeWrite(h.getLevel(),h.absolutePos(TARGET),()->{seen.incrementAndGet();scene.owner.getContraption().stop(h.getLevel());})){scene.visit();}h.assertTrue(seen.get()==1&&scene.actor.isRemoved()&&scene.context.position==null&&h.getBlockState(TARGET).isAir()&&scene.count(GameplayPrintTestFixtures.NBT_CALLBACK.asItem())==1&&scene.count(Items.DIAMOND)==7&&!DeployerSchematicPrinter.hasPending(scene.context),"Actual registered SafeNbt writer stops genuine actor after native protection: no later inventory debit, claim, or world write is authorized");
        }h.succeed();
    }
    @GameTest(structure="create_test:reservoir") public void actualOuterPaymentCallbackRefreshesProtectionAndCachedNativeReceiverMustSurviveFreshPermission(GameTestHelper h)throws Exception{
        try(var session=GameplayAdvancementGameTests.join(h);var blueprint=new Blueprint(h,session.player(),GameplayPrintTestFixtures.NBT_CALLBACK.defaultBlockState());var scene=new Scene(h,session.player(),blueprint.item,GameplayPrintTestFixtures.NBT_CALLBACK.asItem())){
            scene.fund();var target=h.absolutePos(TARGET);var commits=new AtomicInteger();try(var callback=GameplayPrintTestFixtures.afterPaymentCommit(()->{commits.incrementAndGet();DeployerTestFixtures.DENY_USE.add(target);})){scene.visit();}try{h.assertTrue(commits.get()==1&&h.getBlockState(TARGET).isAir()&&scene.count(GameplayPrintTestFixtures.NBT_CALLBACK.asItem())==0&&scene.savedJob().getListOrEmpty("PaidOriginals").size()==1,"Genuine Fabric outer-close callback changes native protection after real payment; original stays in paid job and world remains untouched");}finally{DeployerTestFixtures.DENY_USE.remove(target);}
            var previous=new AtomicReference<GameplayPrintTestFixtures.CallbackNbt>();var replacement=new AtomicReference<GameplayPrintTestFixtures.CallbackNbt>();try(var callback=GameplayPrintTestFixtures.onReceiverPermission(h.getLevel(),target,old->{previous.set(old);var fresh=new GameplayPrintTestFixtures.CallbackNbt(target,h.getLevel().getBlockState(target));fresh.value=99;h.getLevel().removeBlockEntity(target);h.getLevel().setBlockEntity(fresh);replacement.set(fresh);})){scene.retry();}
            h.assertTrue(previous.get()!=null&&replacement.get()!=null&&h.getBlockEntity(TARGET,GameplayPrintTestFixtures.CallbackNbt.class)==replacement.get()&&previous.get().value==0&&replacement.get().value==99&&scene.savedJob().getListOrEmpty("PaidOriginals").isEmpty(),"Actual native permission callback replaces cached receiver with same-state native BE: stale old receiver is never loaded, new receiver data stays99, and genuinely spent base cannot refund");scene.retry();h.assertTrue(h.getBlockEntity(TARGET,GameplayPrintTestFixtures.CallbackNbt.class)==replacement.get()&&replacement.get().value==7&&!DeployerSchematicPrinter.hasPending(scene.context)&&scene.count(GameplayPrintTestFixtures.NBT_CALLBACK.asItem())==0&&scene.count(Items.DIAMOND)==7,"A separate fresh native attempt may install safe source data into that exact current receiver without new payment or another base");
        }h.succeed();
    }

